using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.LoyaltyDiscount;

public class LoyaltyDiscountAcceptanceTests
{
    // Bronze customer is charged the basket subtotal less the Bronze reduction
    [Theory]
    [InlineData(10000, 9500)]
    [InlineData(7, 7)]
    public void S1_BronzeCustomerIsChargedSubtotalLessBronzeReduction(int subtotal, int charged)
    {
        var quote = new CalculateLoyaltyDiscount()
            .Handle(new CalculateLoyaltyDiscountQuery(subtotal, LoyaltyTier.Bronze));

        Assert.Equal(charged, quote.TotalCents);
    }

    // Silver customer is charged the basket subtotal less the Silver reduction
    [Fact]
    public void S2_SilverCustomerIsChargedSubtotalLessSilverReduction()
    {
        var quote = new CalculateLoyaltyDiscount()
            .Handle(new CalculateLoyaltyDiscountQuery(10000, LoyaltyTier.Silver));

        Assert.Equal(9000, quote.TotalCents);
    }

    // Gold customer is charged the basket subtotal less the Gold reduction
    [Fact]
    public void S3_GoldCustomerIsChargedSubtotalLessGoldReduction()
    {
        var quote = new CalculateLoyaltyDiscount()
            .Handle(new CalculateLoyaltyDiscountQuery(10000, LoyaltyTier.Gold));

        Assert.Equal(8500, quote.TotalCents);
    }
}

